/**
 * AEAD Interop Test: ChaCha20-Poly1305 Go ↔ JS
 *
 * Reads testdata/aead_vectors.json (generated by Go with GEN_AEAD_VECTORS=1)
 * and verifies that the JS @stablelib/chacha20poly1305 implementation produces
 * identical ciphertext+tag for each (key, nonce, ad, plaintext) tuple.
 */

import { ChaCha20Poly1305 } from '@stablelib/chacha20poly1305';

// Path relative to this test file — resolved at runtime via require.
const VECTORS_PATH = require('path').join(
  __dirname,
  '../../../../go-shared/pairingcrypto/testdata/aead_vectors.json',
);

interface AEADVector {
  key: string;
  nonce: string;
  ad: string;
  plaintext: string;
  ciphertext: string;
}

function fromHex(hex: string): Uint8Array {
  if (!hex) return new Uint8Array(0);
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

describe('AEAD interop — Go ↔ JS ChaCha20-Poly1305', () => {
  let vectors: AEADVector[];

  beforeAll(() => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      vectors = require(VECTORS_PATH);
    } catch {
      vectors = [];
    }
  });

  it('vector file exists and has entries', () => {
    expect(vectors.length).toBeGreaterThan(0);
  });

  it('JS produces same ciphertext as Go for each vector', () => {
    for (let i = 0; i < vectors.length; i++) {
      const v = vectors[i];
      const key = fromHex(v.key);
      const nonce = fromHex(v.nonce);
      const ad = fromHex(v.ad);
      const plaintext = fromHex(v.plaintext);
      const expectedCT = fromHex(v.ciphertext);

      const aead = new ChaCha20Poly1305(key);
      const ct = aead.seal(nonce, plaintext, ad.length > 0 ? ad : undefined);

      expect(toHex(ct)).toBe(toHex(expectedCT));
    }
  });

  it('JS can decrypt Go-produced ciphertexts', () => {
    for (let i = 0; i < vectors.length; i++) {
      const v = vectors[i];
      const key = fromHex(v.key);
      const nonce = fromHex(v.nonce);
      const ad = fromHex(v.ad);
      const ciphertext = fromHex(v.ciphertext);
      const expectedPT = fromHex(v.plaintext);

      const aead = new ChaCha20Poly1305(key);
      const pt = aead.open(nonce, ciphertext, ad.length > 0 ? ad : undefined);

      expect(pt).not.toBeNull();
      expect(toHex(pt!)).toBe(toHex(expectedPT));
    }
  });
});
